<div class="mb-4"><h1 class="h3">Change password</h1><p class="text-secondary">Use a unique password with at least 12 characters.</p></div><div class="card"><div class="card-body"><form method="post" action="<?= site_url('profile/password') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label" for="current_password">Current password</label><input class="form-control" type="password" id="current_password" name="current_password" autocomplete="current-password" required></div><div class="mb-3"><label class="form-label" for="password">New password</label><input class="form-control" type="password" id="password" name="password" minlength="12" autocomplete="new-password" required></div><div class="mb-3"><label class="form-label" for="password_confirm">Confirm new password</label><input class="form-control" type="password" id="password_confirm" name="password_confirm" minlength="12" autocomplete="new-password" required></div><button class="btn btn-primary">Update password</button></form></div></div>
